(function auth() {
  var mode = 'login', busy = false;
  function txt() { return mode === 'reg' ? 'CRIAR CONTA' : mode === 'reset' ? 'MUDAR SENHA' : 'ENTRAR'; }
  function set(m) { mode = m; $('tabLogin').classList.toggle('sel', m === 'login'); $('tabReg').classList.toggle('sel', m === 'reg'); $('fName').hidden = m === 'login'; $('authBtn').textContent = txt(); $('authErr').textContent = m === 'reset' ? '🔑 Digite o NOME da conta, o E-MAIL do cadastro e a SENHA NOVA.' : ''; $('aPass').placeholder = m === 'reset' ? 'Senha NOVA (mínimo 6)' : 'Senha (mínimo 6)'; $('aName').placeholder = m === 'reset' ? 'Nome da conta' : 'Nome no jogo'; $('auPanel').classList.toggle('three', m !== 'login'); $('forgotBtn').textContent = m === 'reset' ? '↩️ Voltar para entrar' : '🔑 Esqueci a senha'; }
  $('tabLogin').onclick = function () { set('login'); }; $('tabReg').onclick = function () { set('reg'); }; $('forgotBtn').onclick = function () { set(mode === 'reset' ? 'login' : 'reset'); };
  $('aEye').onclick = function () { var v = $('aPass').type === 'password'; $('aPass').type = v ? 'text' : 'password'; this.textContent = v ? '🙈' : '👁️'; };
  function submit() {
    if (busy) return; var email = $('aEmail').value.trim(), pass = $('aPass').value, name = $('aName').value.trim();
    if (mode !== 'login' && name.length < 3) { $('authErr').textContent = 'Digite um nome com pelo menos 3 letras.'; return; } if (!email || !pass) { $('authErr').textContent = 'Digite e-mail e senha.'; return; }
    busy = true; $('authBtn').textContent = 'AGUARDE…'; $('authErr').textContent = ''; session = null;
    api(mode === 'reg' ? '/api/register' : mode === 'reset' ? '/api/reset' : '/api/login', { name: name, email: email, password: pass, cofre: mode === 'login' ? cofreDe(email) : undefined }).then(function (r) {
      if (mode === 'login' && r.error && r.error.code === 'bad-login') { var b = backups()[email.toLowerCase()]; if (b) return api('/api/restore', { name: b.name, email: email, password: pass, save: b.save, profile: b.profile, cofre: cofreDe(email) }).then(function (r2) { return r2.ok ? r2 : r; }); }
      return r;
    }).then(function (r) { busy = false; $('authBtn').textContent = txt(); if (r.error) { $('authErr').textContent = r.error.msg || 'Erro.'; return; } $('aPass').value = ''; if (r.recuperou) G.recup = 1; enter(r, mode === 'reg'); });
  }
  $('authBtn').onclick = submit; $('aPass').onkeydown = function (e) { if (e.key === 'Enter') submit(); };
  var last = store('m3d_last_email'); if (last) { $('aEmail').value = last; if (backups()[last]) $('authErr').textContent = '🔒 Seu progresso está guardado neste celular. Digite sua senha para entrar.'; }
  (function boot() { if (!session) return; api('/api/me').then(function (r) { if (!r.error) return enter(r, false); if (r.error.code === 'net') { $('authErr').textContent = 'Conectando ao servidor…'; setTimeout(boot, 4000); return; } session = null; store('m3d_session', ''); }); })();
})();

